def story_words(story):
    """Все слова истории (в нижнем регистре, без знаков препинания)."""
    import re
    out = []
    for sen in story["sentences"]:
        for w in re.findall(r"[A-Za-zé']+", sen["en"]):
            if w.lower() not in out:
                out.append(w.lower())
    return out
